mapper.select:


    del_flag = '0'

        and report_no like concat('%', #{reportNo}, '%')


        and enterprise_id = #{enterpriseId}


        and enterprise_name like concat('%', #{enterpriseName}, '%')


        and report_status = #{reportStatus}


        and cert_valid_status = #{certValidStatus}


        and exists (
            select 1
            from t_enterprise e
            where e.enterprise_id = t_height_work_report.enterprise_id
              and e.region_code like concat(#{regionCode}, '%')
        )


        and exists (
            select 1
            from t_enterprise e
            where e.enterprise_id = t_height_work_report.enterprise_id
            ${params.regionDataScope}
        )

    ${params.enterpriseDataScope}

        and start_time >= #{startTimeBegin}


        and start_time <= #{startTimeEnd}


order by start_time desc, report_id desc
